insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('metering', 'intermediate', 'module', 'm01-the-choking-boundary', 1, 'Three pressure drop columns run down the marched liquid valve. What separates the stated drop from the drop used?', '["The stated drop is measured at the flange taps and the drop used is corrected back to the vena contracta, so the two differ by the recovery the trim gives back on every row of the march.", "The stated drop is what the process hands the engine, and the drop used is the one the sizing equation is actually given, which is the allowable drop once the service is choked.", "The stated drop is the drop at the design case and the drop used is the drop at the turndown case, so the two differ wherever a turndown flow is given.", "The stated drop carries the static head of the fluid column and the drop used has that head stripped out of it, so the two agree at one elevation."]'::jsonb, 1, 'On the row at an outlet pressure of 200.000000 psia both columns read 46.900000 psi. On the row at an outlet pressure of 40.000000 psia the stated drop is 206.900000 psi and the drop used is 179.220032 psi.'),
  ('metering', 'intermediate', 'module', 'm01-the-choking-boundary', 2, 'What does the allowable drop column do as the outlet pressure is marched from 200.000000 psia down to 20.000000 psia?', '["It falls on every row, because the allowable drop is a fraction of the stated drop and the stated drop is rising as the outlet pressure is taken down the march.", "It holds still down to the row where the engine first reports choked flow and then falls away, because past that row the engine has stopped recomputing it and carries the last value forward.", "It rises on every row, because the allowable drop is recomputed from the outlet pressure and a lower outlet pressure leaves the valve more of the difference to work with.", "It holds the same figure on every row, because it is built from the valve, the fluid and the inlet pressure, and the march moves none of them."]'::jsonb, 3, 'The stated drop changes on every row because a different outlet pressure is being asked for. The allowable drop of 179.220032 psi is the same figure on all nine rows.'),
  ('metering', 'intermediate', 'module', 'm01-the-choking-boundary', 3, 'On which row of the march do the stated drop and the drop used first carry different figures?', '["The row at an outlet pressure of 60.000000 psia.", "The row at an outlet pressure of 80.000000 psia.", "The row at an outlet pressure of 110.000000 psia.", "The row at an outlet pressure of 28.740000 psia."]'::jsonb, 0, 'Above the crossing the two columns agree, all the way down to 80.000000 psia. Below it the drop used stops at 179.220032 psi while the stated drop goes on to 186.900000 psi and past it.'),
  ('metering', 'intermediate', 'module', 'm01-the-choking-boundary', 4, 'The engine counts the rows of this march on which it reports choked flow. What is the count, and what tree and rule stand behind it?', '["4, counted over the 9 outlet pressures asked of the liquid valve, with a row counting when the cavitation index returned there falls below the engine''s exported cavitating threshold.", "5, counted over the 9 marched rows, with a row counting when its regime word carries a cavitation word.", "4, counted over the 9 outlet pressures asked of the liquid valve, with a row counting when the engine returns choked true.", "3, counted over the 9 marched rows, with a row counting when the regime word returned is flashing."]'::jsonb, 2, 'A count with no tree and no rule cannot be checked by anybody reading it. The rule here is the flag itself, so the count is the flag counted and nothing else.'),
  ('metering', 'intermediate', 'module', 'm01-the-choking-boundary', 5, 'How was the outlet pressure at which this valve begins to choke established?', '["By reading the crossing off a chart of coefficient against outlet pressure.", "By setting the stated drop equal to the allowable drop and solving the sizing equation backwards for the outlet pressure that satisfies it.", "By taking the midpoint of the two marched rows that sit either side of the crossing, which is what the engine itself reports as its boundary.", "By bisecting the engine''s own choked flag until the crossing was located between the rows of the march."]'::jsonb, 3, 'The crossing sits at an outlet pressure of 67.679968 psia, with an allowable drop there of 179.220032 psi. It is the engine''s own flag that was bisected, so the figure belongs to the engine rather than to a reading of its output.'),
  ('metering', 'intermediate', 'module', 'm01-the-choking-boundary', 6, 'A hand calculation past the choking boundary reaches for the full stated drop off the datasheet. What is wrong with the coefficient it produces?', '["It is the coefficient for a pressure drop the valve cannot take, so it undersizes the valve while looking entirely reasonable to a reviewer reading the number alone.", "It is the coefficient for a pressure drop the valve cannot take, so it oversizes the valve and leaves the plug near its seat for the normal duty.", "It is computed on a drop the valve can take but at the wrong density, so it is out by the ratio of the flowing density to the density the datasheet quotes.", "It carries no error in the coefficient at all, because the sizing equation is linear in the pressure drop and the two drops cancel out of the answer entirely."]'::jsonb, 0, 'At an outlet of 40.000000 psia the engine, sizing on the drop the valve can use, returns 19.148480, and a sizing on the full stated drop returns 17.821626. The difference, the first less the second, is 1.326854, and the ratio, the first over the second, is 1.074452.'),
  ('metering', 'intermediate', 'module', 'm01-the-choking-boundary', 7, 'Why is the extra pressure drop written on the datasheet unavailable to the valve past the boundary?', '["It is taken by the downstream pipework instead, because the flow at the choking boundary has reached the velocity at which the line itself becomes the controlling restriction.", "It is recovered downstream of the vena contracta and handed back to the process, so the valve never sees it and the net drop across the valve stops rising at the boundary.", "It is dissipated in bubble collapse downstream of the trim rather than in pushing liquid through the restriction, so a calculation that credits the valve with it is crediting it with work the valve does not perform.", "It is absorbed as sensible heat in the liquid, which raises the flowing temperature and with it the vapour pressure, so the drop is spent on a property change instead."]'::jsonb, 2, 'Past the boundary the flow has stopped responding to further reduction in outlet pressure, because the pressure at the vena contracta has fallen to the point where the liquid is vaporising there.'),
  ('metering', 'intermediate', 'module', 'm01-the-choking-boundary', 8, 'What does the engine return on a row where it reports choked flow?', '["A coefficient computed on the allowable drop, with the stated drop rewritten to the allowable figure so one drop is carried.", "A coefficient computed on the allowable drop, together with a message saying the stated drop is beyond what the valve can use.", "A refusal in place of the coefficient, because the engine declines to size a choked service from the ordinary equation.", "A coefficient computed on the stated drop, with a warning that the answer is provisional until a trim is selected."]'::jsonb, 1, 'The engine has still returned a coefficient, so a reader skimming for a number gets one. The sentence beside it is what changes the order that gets placed.'),
  ('metering', 'intermediate', 'module', 'm01-the-choking-boundary', 9, 'The engine''s choked flow message ends with a clause about trim. What does that clause say the service wants?', '["A larger body, one line size up.", "A second valve in series on the same line.", "A hardened seat ring and an expanded outlet.", "A multistage or anti-cavitation trim."]'::jsonb, 3, 'The capped coefficient is a correct answer to the sizing question and a wrong answer to the engineering question, because a standard globe trim asked to hold that drop on this fluid is absorbing continuous bubble collapse against its plug and seat.'),
  ('metering', 'intermediate', 'module', 'm01-the-choking-boundary', 10, 'On the last two rows of the march the regime word reads flashing. What happens to the coefficient and the choked flag there?', '["The coefficient falls again on both rows, because the flashing correction reduces the density the equation is handed.", "The coefficient stays where it settled and the choked flag turns false again, because a flashing service is sized on a two-phase basis rather than on the liquid basis that choked.", "The coefficient stays at the figure it settled on when the drop was capped and the choked flag stays true, so the regime word and the flashing flag record the change.", "The coefficient is withheld on both rows and the choked flag stays true, because the engine refuses to size a flashing service from a liquid equation."]'::jsonb, 2, 'The sizing has been capped and the failure mechanism has changed underneath it. That is why the regime word and the choked flag are two separate returns rather than one.'),
  ('metering', 'intermediate', 'module', 'm01-the-choking-boundary', 11, 'What does marching a valve across nine outlet pressures settle that a single sizing call cannot?', '["Where the valve turns over and how much room is left either side of the turn, which is what a turndown case actually needs to know.", "Whether the coefficient the engine returns at the design point is the coefficient a vendor would quote for the same service on certified trim data.", "Which valve style would place the crossing furthest from the operating range.", "What the inlet pressure of the service is, which nine rows give nine chances to check."]'::jsonb, 0, 'Asked at one operating point a valve either chokes or it does not, and a reviewer has no way of telling whether the answer was close.'),
  ('metering', 'intermediate', 'module', 'm01-the-choking-boundary', 12, 'What does the liquid critical pressure ratio factor set?', '["How much of the pressure the valve took is recovered downstream of the vena contracta, which is the property of the trim that the style table carries.", "How much of the difference between the inlet pressure and the vapour pressure the valve is able to use.", "How far the outlet pressure may fall below the vapour pressure before the engine turns its flashing flag on and changes the regime word it returns.", "What fraction of the stated drop the engine is prepared to size on before it caps the drop and reports the service as choked."]'::jsonb, 1, 'It is a property of the liquid rather than of the valve, and it is computed from the vapour pressure and the critical pressure of the fluid being handled.'),
  ('metering', 'intermediate', 'module', 'm01-the-choking-boundary', 13, 'What value does this factor take as the vapour pressure approaches zero?', '["0.892161", "0.680000", "0.960000", "0.900000"]'::jsonb, 2, 'The engine returns 0.892161 at the marched fluid''s own vapour and critical pressures and 0.680000 at the critical point. The value as the vapour pressure approaches zero is the end of the range that cold hydrocarbon and water service sit near.'),
  ('metering', 'intermediate', 'module', 'm01-the-choking-boundary', 14, 'A cold water service is being sized, well away from its critical pressure. Which of the three returned values of the critical pressure ratio factor does it sit near?', '["The value the engine returns at the critical point.", "The value the engine returns as the vapour pressure approaches zero.", "The value the engine returns at the marched fluid''s own vapour and critical pressures.", "None of the three, because the factor is undefined for a liquid whose vapour pressure is a small fraction of its critical pressure."]'::jsonb, 1, 'Light hydrocarbons at high temperature are where the other end of the range matters. Water at ordinary temperature sits a long way below its critical pressure.'),
  ('metering', 'intermediate', 'module', 'm01-the-choking-boundary', 15, 'Change the fluid on a valve and keep the valve. What happens to the outlet pressure at which the flow chokes?', '["It stays where it was, because the crossing is fixed by the pressure recovery factor of the trim and the trim has not been changed.", "It moves only if the new fluid has a higher vapour pressure than the old one, since the factor is flat below the vapour pressure of the fluid the valve was sized on.", "It stays where it was, because the engine recomputes the crossing from the stated drop and the stated drop is a process figure rather than a fluid one.", "It moves, because the allowable drop moves with the critical pressure ratio factor and the crossing is set by the allowable drop."]'::jsonb, 3, 'It is the reason a valve that behaved perfectly on one service misbehaves on another that looks similar on the datasheet, and the vapour pressure it rests on is an input this engine refuses to work without, because without it the cavitation index cannot form.'),
  ('metering', 'intermediate', 'module', 'm02-cavitation-and-the-screen', 1, 'Every cavitation index this engine returns carries a basis line with it. What does that line say the index was computed on?', '["The stated pressure drop handed to the engine, taken before any cap is applied.", "The difference between the inlet pressure and the vapour pressure of the liquid.", "The pressure drop the valve uses, which is the allowable drop once the service is choked.", "The allowable drop on every row, whether or not the service is choked there."]'::jsonb, 2, 'The engine returns the basis rather than leaving a reader to work it out. Two pressure drops are available on a choked service and only one of the two answers means anything.'),
  ('metering', 'intermediate', 'module', 'm02-cavitation-and-the-screen', 2, 'What is wrong with a cavitation index computed on the stated drop of a choked service?', '["The denominator is a pressure drop the valve is incapable of taking, so the index that comes out belongs to a machine that does not exist.", "The denominator is correct and the numerator is wrong, because the inlet pressure has to be replaced by the pressure at the vena contracta.", "The index comes out negative, because the stated drop on a choked service exceeds the difference between the inlet and the vapour pressure.", "Nothing is wrong with it, because the two drops agree to within the tolerance the engine grades the index at."]'::jsonb, 0, 'The cavitation index is the pressure available to suppress vaporisation divided by the pressure drop being taken.'),
  ('metering', 'intermediate', 'module', 'm02-cavitation-and-the-screen', 3, 'Down the march the cavitation index reads 4.651599, then 2.885714, 2.040786, 1.593572 and 1.307130, and then holds one figure on the last four rows. Why has it stopped moving?', '["The engine rounds the index to six decimals and the remaining change falls below the last place.", "The engine stops recomputing the index once the regime word has reached its last rung.", "The index has reached the exported cavitating threshold and the engine clamps it there.", "It is computed on the drop used, and the drop used has been capped at the allowable drop."]'::jsonb, 3, 'Both the coefficient and the index stopped in the same place and for the same reason. A reader who expects the index to keep falling is expecting a number computed on the stated drop.'),
  ('metering', 'intermediate', 'module', 'm02-cavitation-and-the-screen', 4, 'The vapour pressure box is left empty on a liquid sizing. What does that do to the cavitation screen?', '["The index is zero, the first rung of the ladder is taken, and every liquid service at every pressure drop reads as choked.", "The index is infinite, the last rung of the ladder is taken, and every liquid service at every pressure drop reads as stable.", "The index is returned as a non-finite value and the screen renders an empty cell that a reader can see is empty.", "The index is computed from the critical pressure instead, so the screen runs and reports a regime that is too pessimistic."]'::jsonb, 1, 'The screen renders green and the screen has not run. That is why the repaired engine refuses the call rather than answering it.'),
  ('metering', 'intermediate', 'module', 'm02-cavitation-and-the-screen', 5, 'How does the engine''s refusal on a missing vapour pressure end?', '["`Every liquid has a vapour pressure at its flowing temperature, so state it`", "`Supply a vapour pressure or accept the default for the fluid family named`", "`No vapour pressure was given, so the cavitation index has been suppressed`", "`State a vapour pressure or a critical pressure, and the engine will derive the other`"]'::jsonb, 0, 'The last clause is the one to argue with a datasheet over. An empty box is a missing input rather than a property the fluid lacks.'),
  ('metering', 'intermediate', 'module', 'm02-cavitation-and-the-screen', 6, 'On the row at an outlet pressure of 110.000000 psia the regime word is cavitating and the choked flag is false. What is happening to the valve there?', '["It is choking at the vena contracta while the flag lags a row behind the regime word.", "It is passing less flow than the coefficient implies, because the regime word carries a derate.", "It is being damaged by bubble collapse while the sizing equation is still behaving perfectly.", "It is operating normally, because the engine reserves the word for a condition it has not yet reached."]'::jsonb, 2, 'A valve chosen for a service in that range passes every check a sizing calculation makes, and the failure that follows shows up as a leaking valve and a thinned pipe rather than as a control problem.'),
  ('metering', 'intermediate', 'module', 'm02-cavitation-and-the-screen', 7, 'What would a review that read only the choked flag have concluded about the rows above the crossing?', '["That every one of them is unacceptable, because a false flag is reported only where the sizing has been capped.", "That the rows cannot be judged, because the flag is withheld where a cavitation word appears.", "That the rows either side of the crossing carry the same coefficient.", "That every one of them is acceptable, including the rows the engine itself labels with a cavitation word."]'::jsonb, 3, 'That is the reason the regime word and the choked flag are separate returns. A tool reporting only the flag calls five of the nine rows of this march acceptable.'),
  ('metering', 'intermediate', 'module', 'm02-cavitation-and-the-screen', 8, 'How were the outlet pressures at which the regime word changes established?', '["By solving the index for the sigma at which each rung sits and inverting it for the outlet pressure.", "By bisecting the word the engine returns until each boundary was located.", "By reading them off the marched rows where the word changes.", "By taking the exported thresholds and scaling them on the allowable drop of the valve."]'::jsonb, 1, 'Stable gives way to incipient cavitation at an outlet pressure of 174.180000 psia and incipient gives way to cavitating at an outlet pressure of 137.820000 psia.'),
  ('metering', 'intermediate', 'module', 'm02-cavitation-and-the-screen', 9, 'The engine exports the two sigma values its regime ladder turns on. What does the digest say about where those two values come from?', '["They are read from the published source the recovery factors come from.", "They are derived from the critical pressure ratio factor of the fluid.", "Both belong to this engine, which exports them so that a reader can see what decided the word.", "They are fitted to the marched valve and so belong to that service rather than to the engine."]'::jsonb, 2, 'The engine exports them so that a reader can see exactly what decided the word on the screen, and this course grades no regime word as a result.'),
  ('metering', 'intermediate', 'module', 'm02-cavitation-and-the-screen', 10, 'What does the fact that the two ladder thresholds are exported allow an organisation to do?', '["Read them, replace them with its own cavitation criteria, and say what the word on the screen would have been under its own screen.", "Grade a learner on the regime word, since an exported threshold is a defensible figure.", "Cite the thresholds to a standard, since exporting a value is what publication means.", "Recover the allowable drop of any valve, since the thresholds and the index together fix it."]'::jsonb, 0, 'Because they can be read, they can be replaced, and an organisation can say what its own screen would have returned instead of arguing about a black box.'),
  ('metering', 'intermediate', 'module', 'm02-cavitation-and-the-screen', 11, 'Which of the three rungs of the ladder is different in kind from the other two?', '["The stable to incipient rung, because it is the only one the engine does not export.", "The choking rung, because choking is a hydraulic fact about the valve and the fluid.", "The incipient to cavitating rung, because it is the only one that moves with the fluid.", "None of them, because all three are hydraulic facts rather than screens."]'::jsonb, 1, 'The first two rungs are a judgement about when damage starts to matter, and different organisations draw them in different places.'),
  ('metering', 'intermediate', 'module', 'm02-cavitation-and-the-screen', 12, 'An outlet pressure of 26.740000 psia sits against a vapour pressure of 28.740000 psia. What does the engine return?', '["Flashing true, the regime word cavitating, and a refusal in place of the coefficient.", "Flashing false, because the flag turns on only below the vapour pressure rather than at it.", "Flashing true, with the coefficient recomputed on a two-phase density the engine derives.", "Flashing true, the regime word flashing, and a coefficient."]'::jsonb, 3, 'When the outlet is at or below the vapour pressure the liquid is flashing rather than cavitating, and the engine separates the two and says which one it has.'),
  ('metering', 'intermediate', 'module', 'm02-cavitation-and-the-screen', 13, 'What does the digest print about the outlet pressure at which the flashing flag turns on, set against the stated vapour pressure?', '["A difference of 2.000000 and a ratio of 1.074452, which is the margin the engine leaves before the flag turns on.", "A difference of 0.000000 and a ratio of 0.892161, the fluid''s own critical pressure ratio factor.", "A difference, the first less the second, of 0.000000 and a ratio, the first over the second, of 1.000000.", "No comparison at all, because the engine reports the flag rather than the pressure at which it turned over."]'::jsonb, 2, 'That is as clean a boundary as this course carries. The engine turns the flag on at exactly the vapour pressure, which makes the test the physical statement it appears to be.'),
  ('metering', 'intermediate', 'module', 'm02-cavitation-and-the-screen', 14, 'What does an anti-cavitation trim do for a flashing service?', '["It moves the collapse away from the metal, which is the same thing it does on a cavitating service.", "Nothing, because there is no bubble collapse for it to suppress.", "It restores the coefficient the engine capped, by staging the letdown across several passages.", "It raises the outlet pressure back above the vapour pressure by recovering part of the drop."]'::jsonb, 1, 'In flashing the stream leaves the valve as a two-phase mixture and stays that way, so what is left is an erosion problem in the valve outlet and the downstream pipe.'),
  ('metering', 'intermediate', 'module', 'm02-cavitation-and-the-screen', 15, 'The engine''s flashing message carries three separate instructions. What are they?', '["Size for two-phase flow, use hardened trim, and expand the outlet.", "Size for two-phase flow, fit a multistage trim, and raise the downstream pressure.", "Derate the coefficient, fit hardened trim, and recheck the service at the turndown case.", "Size on the allowable drop, fit an anti-cavitation trim, and expand the outlet."]'::jsonb, 0, 'The engine''s own words are `the outlet is at or below the vapour pressure: this service is FLASHING, and an anti-cavitation trim will not help a flashing service. Size for two-phase flow and use hardened trim with an expanded outlet`.'),
  ('metering', 'intermediate', 'module', 'm03-gas-sizing-and-whose-table', 1, 'On gas the choking boundary is a pressure drop ratio. What is that ratio?', '["The outlet pressure divided by the inlet pressure.", "The pressure drop divided by the inlet pressure.", "The pressure drop divided by the outlet pressure.", "The inlet pressure divided by the vapour pressure."]'::jsonb, 1, 'The engine returns it on every gas sizing along with the terminal value it is being compared against. It is written x.'),
  ('metering', 'intermediate', 'module', 'm03-gas-sizing-and-whose-table', 2, 'The gas valve is marched down its outlet pressure. What is the pressure drop ratio on the row at an outlet pressure of 90.000000 psia?', '["0.554475", "0.716484", "0.635480", "0.688654"]'::jsonb, 2, 'The ratio reads 0.554475 on the row at an outlet pressure of 110.000000 psia and 0.716484 on the row at an outlet pressure of 70.000000 psia.'),
  ('metering', 'intermediate', 'module', 'm03-gas-sizing-and-whose-table', 3, 'On how many rows of the gas march does the engine report choked flow, and over what tree and rule?', '["3, over the 9 gas outlet pressures, with the choked flag alone deciding membership.", "5, counted over the 9 outlet pressures asked of the gas valve, with a row counting when the expansion factor returned there has reached its floor.", "4, counted over the 9 outlet pressures asked of the gas valve, with a row counting when the engine returns choked true.", "6, over the 9 gas outlet pressures, admitted where x exceeds one half."]'::jsonb, 0, 'Membership is decided by the flag and by nothing else, which is what makes the figure something a reader can go and recount.'),
  ('metering', 'intermediate', 'module', 'm03-gas-sizing-and-whose-table', 4, 'Two things follow from the gas boundary being a ratio rather than a pressure. What are they?', '["It is dimensionless, so the valve''s part of it, xT, can be quoted for a style without knowing the service, and the pressure it corresponds to is fixed once the style is chosen.", "It carries units of pressure over pressure, so it has to be restated whenever the units of the datasheet change, and it moves with the outlet pressure alone.", "It is dimensionless, so it applies unchanged to liquid service as well, and the pressure it corresponds to is the same at every inlet condition the plant reaches.", "It is dimensionless, so the valve''s part of it, xT, can be quoted for a style without knowing the service, and the pressure it corresponds to depends on the inlet pressure."]'::jsonb, 3, 'That is why a gas valve has to be checked at every inlet condition the plant can reach rather than at the design case alone.'),
  ('metering', 'intermediate', 'module', 'm03-gas-sizing-and-whose-table', 5, 'What happens to a familiar rule of thumb that carries a pressure drop in the head as an absolute figure?', '["It survives unchanged, because the engine converts an absolute drop into a ratio before it compares anything.", "It does not survive contact with the gas boundary, because the same absolute drop is a small ratio at a high inlet pressure and a large one at a low inlet pressure.", "It survives on any service below the terminal value, because the ratio and the absolute drop agree there.", "It becomes conservative, because an absolute drop always corresponds to a ratio above the terminal value."]'::jsonb, 1, 'On gas the boundary moves with the inlet pressure, so a valve comfortably below it at one inlet condition can be past it at another.'),
  ('metering', 'intermediate', 'module', 'm03-gas-sizing-and-whose-table', 6, 'What does the expansion factor correct for?', '["The gas expanding through the valve, which lowers the density in the throat so that less mass passes than an incompressible calculation would predict.", "The gas being compressed through the valve, which raises the density in the throat so that more mass passes than an incompressible calculation predicts.", "The difference between the specific heat ratio of the gas handled and the specific heat ratio of the gas the valve was certified on.", "The recovery of pressure downstream of the vena contracta, which returns part of the drop the valve took and reduces the effective drop."]'::jsonb, 0, 'It is where the gas choking boundary shows itself in the arithmetic. It falls with the pressure drop ratio and is floored.'),
  ('metering', 'intermediate', 'module', 'm03-gas-sizing-and-whose-table', 7, 'Why is the floor on the expansion factor exactly two thirds?', '["It is a rounding of the ratio of the specific heats of air, which is the gas that valve terminal ratios are quoted on.", "It is a convention this engine adopted so that the factor reaches a readable figure at the boundary.", "It is the value the linear form takes at its own terminal point, which is why it is the same figure on every choked gas service anybody sizes.", "It is the fraction of the inlet density the throat density falls to when the flow becomes sonic in the vena contracta."]'::jsonb, 2, 'The factor falls linearly with the pressure drop ratio and the terminal ratio is where it is floored. Put the terminal ratio into the linear form and the factor comes out at two thirds of unity, for every valve style and every gas.'),
  ('metering', 'intermediate', 'module', 'm03-gas-sizing-and-whose-table', 8, 'What does the engine size on once the pressure drop ratio has reached its terminal value?', '["The stated ratio, because the terminal value screens the service rather than entering the arithmetic of the answer.", "The ratio halfway between the stated and the terminal value, which is the engine''s stated compromise at the boundary.", "Nothing, because the engine withholds the coefficient on a choked gas service and returns the terminal ratio alone.", "The terminal ratio, because past it the flow is sonic in the vena contracta and further pressure drop buys nothing."]'::jsonb, 3, 'The engine says so with the answer: `choked flow: x of 0.878 is at or past the terminal 0.680, so the flow is sonic in the vena contracta and further pressure drop buys nothing. The terminal ratio has been used for sizing, and the noise and trim wear at this condition need a multistage trim`.'),
  ('metering', 'intermediate', 'module', 'm03-gas-sizing-and-whose-table', 9, 'Which half of the gas choked flow message is the half people skip?', '["The sizing half, which says the terminal ratio has been used for sizing and that the coefficient beside it is correct.", "The engineering half, which says the noise and the trim wear at that condition need a multistage trim.", "The opening clause, which gives the pressure drop ratio and the terminal ratio it has reached.", "The closing clause, which names the standard the terminal ratio was read from."]'::jsonb, 1, 'A gas valve running sonic in the throat is a noise and wear problem whatever its coefficient says, and the remedy is staged letdown rather than a larger body.'),
  ('metering', 'intermediate', 'module', 'm03-gas-sizing-and-whose-table', 10, 'What does the specific heat ratio factor return at a specific heat ratio of 1.100000?', '["0.857143", "0.785714", "0.928571", "1.185714"]'::jsonb, 1, 'A specific heat ratio of 1.100000 covers the heavier hydrocarbon gases and the richer process streams. The factor at 1.200000 is 0.857143 and at 1.300000 it is 0.928571.'),
  ('metering', 'intermediate', 'module', 'm03-gas-sizing-and-whose-table', 11, 'At which of the specific heat ratios in this course does the factor return exactly 1.000000?', '["1.300000", "1.200000", "1.400000", "1.660000"]'::jsonb, 2, 'Air at ordinary conditions sits at a specific heat ratio close to that value, which tells you what the factor is for: it scales a valve''s terminal behaviour, quoted on air, onto the gas actually being handled.'),
  ('metering', 'intermediate', 'module', 'm03-gas-sizing-and-whose-table', 12, 'Where does the specific heat ratio factor show its effect?', '["At every operating point equally, because it multiplies the coefficient the sizing equation returns.", "Only on services above the terminal ratio, because below it the factor is held at unity by the engine.", "Only at the boundary, because it multiplies the terminal ratio and leaves the coefficient at a given operating point alone.", "At every operating point through the expansion factor, and at the boundary through the terminal ratio it multiplies."]'::jsonb, 3, 'Fk multiplies xT to set the terminal ratio, and it sits inside the expansion factor on every row, where Y is one less x over three times Fk times xT. So it moves the coefficient everywhere and the boundary as well, which is why a stream whose composition changes with plant mode has to be checked at each mode.'),
  ('metering', 'intermediate', 'module', 'm03-gas-sizing-and-whose-table', 13, 'How many valve styles does this engine carry, and over what tree and rule?', '["5, counted over the styles array the module exports, with an entry counting when it carries both a pressure recovery factor and a terminal ratio.", "8, counted over the styles array the module exports, with every entry counting and no filter applied.", "8, counted over the styles array the module exports, with an entry counting when its label names a globe or a ball.", "4, counted over the styles array the module exports, with an entry counting when its pressure recovery factor is above one half."]'::jsonb, 1, 'The tree is the exported array and the rule is that nothing is filtered out of it, which is what makes the count checkable by anybody who can read the export.'),
  ('metering', 'intermediate', 'module', 'm03-gas-sizing-and-whose-table', 14, 'The engine states the status of its own pressure recovery factors and terminal ratios. What does it instruct?', '["That they may be used unchanged wherever the style label matches the valve supplied.", "That they should be interpolated between styles when the trim supplied sits between two.", "That a certified vendor figure for the specific trim always replaces them.", "That they are cited to a published document and may be quoted against it in a calculation."]'::jsonb, 2, 'The message is `the FL and xT above are this engine''s stated table values. They are not cited to a document in this repository, they are trim and vendor dependent by nature, and a certified vendor figure for the specific trim always replaces them`.'),
  ('metering', 'intermediate', 'module', 'm03-gas-sizing-and-whose-table', 15, 'Why is the choice of valve style a sizing decision rather than a procurement detail?', '["The allowable drop is built from the pressure recovery factor, so the same service on two styles with different FL chokes at two different outlet pressures.", "The coefficient is read off the style, so the same service on two different styles returns two different flows at the same drop.", "The terminal ratio is what the engine sizes every liquid service on, so the style decides the drop used on liquid and on gas alike.", "The style decides the rangeability, so the same service on two different styles lands at two different travels at its normal duty."]'::jsonb, 0, 'A valve type chosen for cost or for space can move a boundary that the process never asked to move.'),
  ('metering', 'intermediate', 'module', 'm04-authority-and-the-characteristic', 1, 'What is valve authority?', '["The fraction of its own travel the valve uses between the minimum and the maximum duty.", "The ratio of the coefficient the valve carries to the coefficient the design case needs.", "The fraction of the system''s total pressure drop that the valve itself takes at design flow.", "The share of the total flow the valve passes when the loop is at its design set point."]'::jsonb, 2, 'The rest of the drop is taken by the pipe, the fittings, the exchangers and everything else in the circuit.'),
  ('metering', 'intermediate', 'module', 'm04-authority-and-the-characteristic', 2, 'A system carries a total drop of 120.000000 psi and the valve takes 25.000000 psi of it. What authority does the engine return?', '["0.333333", "0.208333", "0.083333", "0.458333"]'::jsonb, 1, 'A valve drop of 40.000000 psi on the same system gives 0.333333 and a valve drop of 10.000000 psi gives 0.083333.'),
  ('metering', 'intermediate', 'module', 'm04-authority-and-the-characteristic', 3, 'On that same 120.000000 psi system the valve is given 70.000000 psi. What is the authority?', '["0.708333", "0.833333", "0.458333", "0.583333"]'::jsonb, 3, 'Seven valve drops are run against one total in the digest, and this rung is the fifth of them.'),
  ('metering', 'intermediate', 'module', 'm04-authority-and-the-characteristic', 4, 'Why does a valve with a small share of the system drop make a loop hard to tune?', '["Opening it hands most of the newly released pressure to the pump, so the flow overshoots and the gain changes enormously across the range.", "Opening it hands most of the newly released pressure straight to the pipework, so the flow barely moves and the gain changes enormously across the range.", "Opening it changes the flow faster than the controller can act, so the loop gain is even but the dead time swamps it at every set point.", "Opening it leaves the drop across the circuit unchanged, so the flow rises in exact proportion to travel and the loop has no gain to work with."]'::jsonb, 1, 'As the flow rises the drop taken by the rest of the circuit rises with it, because friction losses go up with flow, and the total available is fixed by the pump and the system.'),
  ('metering', 'intermediate', 'module', 'm04-authority-and-the-characteristic', 5, 'Where does the total system drop the authority is taken against have to come from?', '["The valve datasheet, where the supplier states it beside the rated coefficient of the trim offered.", "The difference between the pump shut-in head and the vessel operating pressure.", "A hydraulic calculation of the whole circuit at design flow, produced by somebody.", "The engine, which derives it from the valve drop and the returned authority."]'::jsonb, 2, 'Where that figure is a guess, the authority is a guess, and the verdict beside it inherits the guess without showing it.'),
  ('metering', 'intermediate', 'module', 'm04-authority-and-the-characteristic', 6, 'The engine states where its two authority boundaries come from. What does the message say?', '["`the 0.5 and 0.25 boundaries are this engine''s stated screen, and no standard in this package supplies them`", "`the 0.5 and 0.25 boundaries are drawn from the installed characteristic literature and apply to modulating service`", "`the 0.5 and 0.25 boundaries are the limits at which the installed gain doubles and halves across the travel`", "`the 0.5 and 0.25 boundaries were chosen so that a linear trim is recommended wherever the loop can be tuned`"]'::jsonb, 0, 'A verdict word carries an air of authority that a bare fraction does not. What the engine is saying is that the word is the output of a screen it states for itself.'),
  ('metering', 'intermediate', 'module', 'm04-authority-and-the-characteristic', 7, 'Why should a document quote the authority alongside the verdict?', '["A reader given the fraction can recover the total system drop from it, which the word alone does not carry.", "A reader given the fraction can apply their own company screen to it, and a reader given the word alone cannot recover anything.", "A reader given the fraction can tell which characteristic was recommended, which the word alone leaves open.", "A reader given the fraction can check it against the standard the boundaries are read from, which the word hides."]'::jsonb, 1, 'The verdict is a word with no units and no visible arithmetic behind it, so it travels further than the fraction does and arrives somewhere being read as though a standard had said it.'),
  ('metering', 'intermediate', 'module', 'm04-authority-and-the-characteristic', 8, 'Which valve drop on the 120.000000 psi system returns an authority of 0.833333?', '["85.000000 psi", "55.000000 psi", "the whole 120.000000 psi", "100.000000 psi"]'::jsonb, 3, 'The ladder runs 10.000000, 25.000000, 40.000000, 55.000000, 70.000000, 85.000000 and 100.000000 psi against one total, and the characteristic recommendation changes at an authority of 0.500000.'),
  ('metering', 'intermediate', 'module', 'm04-authority-and-the-characteristic', 9, 'The engine gives a reason for its recommendation on the high authority cases. What is that reason?', '["The valve takes most of the system drop, so its inherent curve is far from its installed curve and linear trim restores the balance.", "The valve takes most of the system drop, so the installed curve steepens at the top of the range and linear trim flattens it again.", "The valve takes most of the system drop, so its inherent curve is close to its installed curve and linear trim gives even loop gain.", "The valve takes most of the system drop, so the rangeability of the trim is the limit on control rather than the shape of the curve."]'::jsonb, 2, 'When the valve takes most of the drop there is almost nothing to cancel, so linear trim is the choice that leaves the gain even.'),
  ('metering', 'intermediate', 'module', 'm04-authority-and-the-characteristic', 10, 'What does the engine say equal percentage trim is shaped to cancel?', '["The flattening of the installed curve that happens because the system absorbs most of the drop as flow rises.", "The steepening of the installed curve that happens because the pump head falls away as flow rises.", "The dead band in the positioner, which otherwise leaves the plug behind the controller output.", "The nonlinearity of the process itself, which is what the loop is ultimately being asked to hold."]'::jsonb, 0, 'The engine''s words are `the system absorbs most of the drop as flow rises, which flattens the installed curve. Equal-percentage trim is shaped to cancel exactly that and restore something close to linear installed gain`.'),
  ('metering', 'intermediate', 'module', 'm04-authority-and-the-characteristic', 11, 'What shape is the equal percentage curve?', '["It passes a great deal near the seat and very little near full travel.", "It passes very little near the seat and a great deal near full travel.", "It passes the same increment of flow for each increment of travel throughout.", "It passes most of its range within the first quarter of travel and then flattens."]'::jsonb, 1, 'That is a curve bent in the opposite direction to the distortion the circuit applies, which is why the two together leave the loop something close to a straight line.'),
  ('metering', 'intermediate', 'module', 'm04-authority-and-the-characteristic', 12, 'What happens when equal percentage trim is fitted to a circuit that applies no such distortion?', '["The loop behaves as though linear trim had been fitted, because the two curves agree at high authority.", "The loop cannot reach its design flow, because the equal percentage curve passes less at full travel.", "The loop gain is even, because the trim curve is the one the installed curve is measured against.", "The loop is bent the other way instead, because the trim is cancelling something that is not there."]'::jsonb, 3, 'The trim is chosen to cancel a known distortion. That is also why the recommendation is read off the authority rather than off the service.'),
  ('metering', 'intermediate', 'module', 'm04-authority-and-the-characteristic', 13, 'Two functions in this module talk about inherent characteristics. What is asserted about the words they exchange?', '["Every id the recommendation returns is an id the travel check accepts, and it is asserted on the two rows where the recommendation changes.", "Every id the recommendation returns is an id the travel check accepts, and it is asserted once when the module loads rather than per row.", "Every id the recommendation returns is an id the travel check accepts, and it is asserted on every row of the authority ladder.", "The two functions carry separate vocabularies and the engine maps between them, which is why an unknown word can still be handled."]'::jsonb, 2, 'A recommendation phrased in a vocabulary the travel check did not recognise would strand the user at exactly the point where they were doing the right thing.'),
  ('metering', 'intermediate', 'module', 'm04-authority-and-the-characteristic', 14, 'Which two inherent characteristics does the travel check know?', '["equalPercentage and linear", "linear and quickOpening", "equalPercentage and modifiedParabolic", "linear and modifiedParabolic"]'::jsonb, 0, 'The engine''s refusal names them itself: `unknown inherent characteristic ''quickOpening'': this module knows equalPercentage and linear. An unrecognised characteristic used to be treated silently as equal percentage`.'),
  ('metering', 'intermediate', 'module', 'm04-authority-and-the-characteristic', 15, 'A silent default in place of a refusal is the failure mode this module is built to avoid. Why is it so dangerous?', '["It produces an answer of the wrong type, which fails loudly at the next step and wastes the time of whoever traces it.", "It produces an answer of the right type and the wrong value, and nothing downstream can tell that it happened.", "It produces no answer at all, so the user is left with a blank cell and no statement of what was missing.", "It produces an answer that is right at the ends of the range and wrong in the middle, which is where reviews look."]'::jsonb, 1, 'The refusal fires at the travel check, which is the function that was handed the unknown word. A refusal belongs at the boundary a bad value crosses, because that is the only place that knows both what arrived and what was expected.'),
  ('metering', 'intermediate', 'module', 'm05-noise-as-an-indication', 1, 'The engine''s note comes back with every noise indication. What does it say the result is?', '["A prediction at a stated distance.", "A screening indication only.", "A guaranteed sound pressure level.", "A band read from a published table."]'::jsonb, 1, 'Four claims are packed into that note. The result is an indication, a prediction needs a named method and geometry this package does not have, the band is there to tell you whether to ask the question, and the thresholds behind it belong to the engine.'),
  ('metering', 'intermediate', 'module', 'm05-noise-as-an-indication', 2, 'Which published method does the note name?', '["The IEC 60534-8-3 method.", "The ISO pipe lagging method.", "The API machinery noise method.", "The ISA control valve sizing method."]'::jsonb, 0, 'The note names it rather than leaving the gap unstated, which is what makes the gap something a reader can act on.'),
  ('metering', 'intermediate', 'module', 'm05-noise-as-an-indication', 3, 'Beyond the named method, what two things does the engine say a real prediction needs?', '["A fluid property set and an ambient temperature.", "A measured background level and a receiver distance.", "A trim style and a certified pressure recovery factor.", "Valve geometry and pipe geometry."]'::jsonb, 3, 'Neither one is a fluid property. They are missing because the indication takes the service alone, its pressures, flow, gas gravity and temperature, and never a drawing.'),
  ('metering', 'intermediate', 'module', 'm05-noise-as-an-indication', 4, 'Why does the geometry matter so much to a real prediction?', '["Noise generated inside the trim is carried by the fluid rather than by the wall, so the line length and the number of bends decide what reaches somebody standing on the plant.", "Noise generated inside the trim is proportional to the internal volume of the body, so the face to face dimension and the port area fix the acoustic power at source.", "Noise generated inside the trim gets out through the pipe wall downstream, so the diameter, the wall thickness, the material and any lagging all decide what reaches somebody standing on the plant.", "Noise generated inside the trim reflects off the downstream reducer, so the expansion ratio at the outlet sets how much of it returns into the valve and is absorbed there."]'::jsonb, 2, 'The trim geometry matters for the same kind of reason. A cage with many small passages and a single plug in a large port can dissipate identical power and radiate very different acoustic spectra.'),
  ('metering', 'intermediate', 'module', 'm05-noise-as-an-indication', 5, 'What does a screening band leave you unable to do?', '["Rank a population of valves against one another, which is what a concept stage cost estimate is actually asking the screen for.", "Defend a number, support a guarantee, or settle a dispute with a vendor about a decibel figure at a stated distance.", "Decide which valves to raise with a noise specialist, which needs the named method instead.", "Tell whether a service is above or below the thresholds the engine exports for the screen."]'::jsonb, 1, 'A screen is a triage tool. On a plant with several hundred control valves the useful question at concept stage is which ten of them need a specialist, an acoustic lagging allowance or a low noise trim in the cost estimate.'),
  ('metering', 'intermediate', 'module', 'm05-noise-as-an-indication', 6, 'What is the pressure ratio of the one scfh bleed probe?', '["12.000000", "1.898734", "6.000000", "2.000000"]'::jsonb, 0, 'The engine also runs a hundred million scfh probe at a ratio of 1.898734 and a moderate station flow at a ratio of 6.000000.'),
  ('metering', 'intermediate', 'module', 'm05-noise-as-an-indication', 7, 'A transmission volume is throttled across a valve and the screen is run on it. Which of these is its pressure ratio?', '["12.000000", "6.000000", "1.898734", "4.000000"]'::jsonb, 2, 'The probe is described as a hundred million scfh at a pressure ratio near two, and on the ratio alone it would have read low.'),
  ('metering', 'intermediate', 'module', 'm05-noise-as-an-indication', 8, 'Why is the noise screen built on the ratio of the pressures rather than on their difference?', '["The difference is not available to the engine at all, because a gas sizing call carries the outlet pressure alone and nothing else.", "The difference carries units of pressure, and a screen that carries units cannot be applied across a population of valves at all.", "The difference is already inside the stream power term, so using it twice would count the same energy twice.", "The ratio decides how far the gas expands through the trim, which is what turns pressure energy into acoustic power."]'::jsonb, 3, 'A valve dropping a large absolute pressure from a very high inlet may sit at a modest ratio, and a valve dropping a small absolute pressure from a low inlet may sit at a large one.'),
  ('metering', 'intermediate', 'module', 'm05-noise-as-an-indication', 9, 'What is the stream power of a service?', '["The acoustic power radiated by the valve body, which is the fraction of the mechanical power dissipated in it that leaves as sound.", "The energy the gas gives up expanding through the valve, formed from the mass flow, the absolute temperature and the log of the pressure ratio.", "The kinetic energy of the stream leaving the valve, taken at the velocity in the outlet connection.", "The thermal power the stream carries, taken as the mass flow times the specific heat times the drop."]'::jsonb, 1, 'It is the size of the energy stream the noise has to come out of. A trickle cannot be loud however hard it is throttled.'),
  ('metering', 'intermediate', 'module', 'm05-noise-as-an-indication', 10, 'On how many of the noise probes did the stream power move the band off the pressure ratio alone, and over what tree and rule?', '["2, counted over the 3 noise probes asked of the indication, with a probe counting when its stream power sits outside the two exported power thresholds.", "3, counted over the 3 noise probes asked of the indication, with a probe counting when the engine returns a non-null power effect.", "3, counted over the 3 noise probes asked of the indication, with a probe counting when the final band sits below the band the ratio proposed.", "2, counted over the 3 noise probes asked of the indication, with a probe counting when the engine returns a non-null power effect."]'::jsonb, 3, 'A probe is admitted by the power effect and by nothing else, so the figure can be recounted by anybody who can read the three results.'),
  ('metering', 'intermediate', 'module', 'm05-noise-as-an-indication', 11, 'What does the engine say about the one scfh bleed?', '["`held down to low: the stream power of 0.00134 kW is below 1 kW, and a bleed of this size is exempt from the screen entirely. On the pressure ratio alone this service would have read severe`", "`raised to moderate: the stream power of 0.00134 kW is below 1 kW, so the ratio alone has understated this service and the band has been moved up one rung`", "`held down to low: the stream power of 0.00134 kW is below 1 kW, and a trickle cannot be loud however hard it is throttled. On the pressure ratio alone this service would have read severe`", "`held down to low: the pressure ratio of 12.000000 is above the severe threshold, so the band has been capped at the lowest rung the screen carries`"]'::jsonb, 2, 'The probe''s stream power is 0.00133650 kW against a pressure ratio of 12.000000, and the message is what says which way the band moved and why.'),
  ('metering', 'intermediate', 'module', 'm05-noise-as-an-indication', 12, 'Which message does the indication return on the hundred million scfh probe?', '["`raised to moderate: the stream power of 34486.0 kW is above 1000 kW, which is not a quiet valve at any pressure ratio. On the pressure ratio alone this service would have read low`", "`raised to severe: the stream power of 34486.0 kW is above 1000 kW, which is not a quiet valve at any pressure ratio at all. On the pressure ratio alone this service would have read low`", "`raised to moderate: the stream power of 34486.0 kW is above 1000 kW, so the pressure ratio has been recomputed on the flowing density and the band for this service taken again`", "`raised to moderate: the flow of a hundred million scfh is above the screen''s own flow threshold, so the band the ratio proposed has been overruled`"]'::jsonb, 0, 'The final band on that probe is moderate and its ratio band is low, which is the whole reason the screen takes two variables rather than one.'),
  ('metering', 'intermediate', 'module', 'm05-noise-as-an-indication', 13, 'The third probe is a moderate station flow at a pressure ratio near six. What does the engine return for it?', '["A ratio of 6.000000, a stream power of 2312.85 kW, a ratio band of high and a band of severe.", "A ratio of 6.000000, a stream power of 2312.85 kW, a ratio band of high and a band of high.", "A ratio of 6.000000, a stream power of 2312.85 kW, a ratio band of moderate and a band of high.", "A ratio of 6.000000, a stream power of 34486.0 kW, a ratio band of high and a band of high."]'::jsonb, 1, 'The engine names the two probes where the power moved the band and this is not one of them, so the screen is leaving the ratio''s proposal where it found it.'),
  ('metering', 'intermediate', 'module', 'm05-noise-as-an-indication', 14, 'What does a screen built on the pressure ratio alone get wrong, in both directions at once?', '["It proposes a trickle as low and a large transmission flow as severe, because the ratio is dominated by the flow passing through the trim rather than by the expansion across it.", "It proposes every service in the middle of the range, because a ratio compresses the spread of a population into a narrow band of values.", "It proposes a trickle as severe and a large transmission flow as low, because the ratio knows how hard the gas is throttled and nothing about how much gas there is.", "It proposes the right band on gas and the wrong band on liquid, because a pressure ratio has no meaning where the fluid does not expand."]'::jsonb, 2, 'Flagging a trickle as severe wastes a specialist''s time and fills a register with entries nobody can close. Reporting a large transmission valve as low is the failure that ends with acoustic lagging missing from an estimate.'),
  ('metering', 'intermediate', 'module', 'm05-noise-as-an-indication', 15, 'What is the failure this module is written to prevent?', '["The use of a screening output at concept stage, which is where a named method should be applied instead.", "The reporting of a screening output to a vendor, which invites a quotation against a band rather than a level.", "The recording of a screening output in a register, which leaves an item open that nobody has the evidence to close.", "The quiet promotion of a screening output into a design value, which happens when a band word is copied out of a tool into a table with no note attached."]'::jsonb, 3, 'The honest way to report a screening result is to say what the tool did, say what it did not do, and say what happens next.'),
  ('metering', 'intermediate', 'module', 'm06-travel-rangeability-and-the-verdict', 1, 'Three flows are given and all three checks run clean. What is the minimum duty travel, in percent open?', '["37.222222", "47.956430", "74.737770", "83.997848"]'::jsonb, 1, 'On that case the normal duty sits at 74.737770 percent open and the maximum duty at 83.997848 percent open, with 3 of the 3 checks run, a verdict of true and 0 warnings.'),
  ('metering', 'intermediate', 'module', 'm06-travel-rangeability-and-the-verdict', 2, 'The same valve is asked for a minimum flow that is hard against its seat. What does the engine report?', '["A minimum travel of 0.000000 percent open, 2 of the 3 checks run, a verdict of null and 1 warning.", "A minimum travel withheld by name, all 3 checks run, a verdict of false and 1 warning.", "A minimum travel of 47.956430 percent open, all 3 checks run, a verdict of false and 0 warnings.", "A minimum travel of 0.000000 percent open, all 3 checks run, a verdict of false and 1 warning."]'::jsonb, 3, 'A valve at 0.000000 percent open is shut, and the travel is a number the engine computed and is prepared to defend.'),
  ('metering', 'intermediate', 'module', 'm06-travel-rangeability-and-the-verdict', 3, 'What does a loop do when its minimum duty lands on the seat?', '["It loses proportional control at the low end, so the only thing left is a sequence of openings and closings the process sees as a cycle.", "It loses proportional control at the low end, so the controller saturates at full travel and the process runs above its set point.", "It keeps control but with a large offset, because the plug meters against the seat land at a coefficient the trim can still resolve.", "It keeps control and loses only its speed of response, because the positioner has to drive the plug off the seat before flow starts."]'::jsonb, 0, 'Seats are damaged by exactly that duty, because the trim is being landed repeatedly under a full pressure drop.'),
  ('metering', 'intermediate', 'module', 'm06-travel-rangeability-and-the-verdict', 4, 'The maximum duty on the healthy case sits at 83.997848 percent open. What is worth noticing about that?', '["There is no travel left in hand above it at all, which is the reason the engine raises a warning on that case rather than a clean verdict.", "It is the highest travel the engine will ever report on any case, because the check is bounded at the top of the stroke and clips there.", "There is travel left in hand above it, which a valve reaching its design flow at the top of its stroke would not have.", "It is the travel at which the engine switches from the equal percentage curve to the linear one."]'::jsonb, 2, 'A valve that reaches its design flow only at the very top of its stroke has nothing left for a fouled exchanger, a worn pump or an off design day.'),
  ('metering', 'intermediate', 'module', 'm06-travel-rangeability-and-the-verdict', 5, 'What decides the travel that a required coefficient corresponds to?', '["The valve authority and the total system drop.", "The inherent characteristic and the rangeability of the trim.", "The pressure recovery factor and the allowable drop.", "The minimum flow and the maximum flow the check was handed for the duty."]'::jsonb, 1, 'Rangeability is the span between the largest and the smallest coefficient the trim can meter with, and both it and the characteristic are properties the vendor states for the specific trim.'),
  ('metering', 'intermediate', 'module', 'm06-travel-rangeability-and-the-verdict', 6, 'Equal percentage trim at a rangeability of 50 puts the normal duty at 74.737770 percent open. Where does linear trim put it, in percent open?', '["47.956430", "83.997848", "37.222222", "0.000000"]'::jsonb, 2, 'The duty has not changed. The flow, the pressure drop, the fluid and the required coefficient are all the same on both, and only the shape of the relationship between travel and coefficient has changed.'),
  ('metering', 'intermediate', 'module', 'm06-travel-rangeability-and-the-verdict', 7, 'The digest sets those two travels against each other. What ratio does it print, the first over the second?', '["1.021201", "1.074452", "1.763636", "2.007880"]'::jsonb, 3, 'It prints 37.515548 for the difference of the first less the second on the same line. Computed and printed is what allows a comparison to be quoted at all.'),
  ('metering', 'intermediate', 'module', 'm06-travel-rangeability-and-the-verdict', 8, 'Why does the equal percentage figure sit further up the stem than the linear one?', '["Equal percentage trim passes a great deal near the seat and very little near the top of its travel, so the same coefficient needs more opening.", "Equal percentage trim is rated at a larger coefficient at full travel, so a given duty is a smaller fraction of what the trim can pass.", "Equal percentage trim passes very little near the seat and a great deal near the top of its travel, so the same coefficient needs more opening.", "Equal percentage trim is fitted with a longer stroke, so the same fraction of the coefficient corresponds to a longer travel in inches."]'::jsonb, 2, 'The stem position is the visible consequence of the curve, which is the whole reason a characteristic is chosen.'),
  ('metering', 'intermediate', 'module', 'm06-travel-rangeability-and-the-verdict', 9, 'A travel percentage arrives on a datasheet with nothing else beside it. Why can it not be read?', '["Nothing says which of the three duties it belongs to, and the check reports the normal duty alone in any case.", "Nothing says which curve it was taken off or over what span of coefficient the trim meters.", "Nothing says whether it was measured on the stem itself, and no coefficient can be turned into a travel here.", "Nothing says what pressure drop it was taken at, and travel moves with the drop."]'::jsonb, 1, 'A rangeability assumed rather than confirmed moves every travel figure a check produces, and the low end is precisely where the verdict turns.'),
  ('metering', 'intermediate', 'module', 'm06-travel-rangeability-and-the-verdict', 10, 'A plug that operates around three quarters open is often assumed to be undersized. Why is that assumption unsafe?', '["On equal percentage trim that is a normal working position, and the assumption comes from being accustomed to linear trim.", "On equal percentage trim that position is the rangeability limit, so the valve is already at the end of what the trim can meter.", "On equal percentage trim the travel is reported against the maximum duty rather than against full stroke, so the figure is not comparable.", "On equal percentage trim the engine reports travel in the coefficient''s own units, so a percentage read off it means something else entirely."]'::jsonb, 0, 'The figures in this module are on equal percentage trim at a rangeability of 50, and a travel percentage without its characteristic and its rangeability cannot be read.'),
  ('metering', 'intermediate', 'module', 'm06-travel-rangeability-and-the-verdict', 11, 'The engine separates two ways of having no maximum flow travel. What states does it report?', '["`beyond the valve` where the flow never arrived, and `not given` where the duty is past what the trim can pass.", "`out of range` where the duty is past what the trim can pass, and `withheld` where the flow never arrived.", "`null` in both cases, with the distinction carried in the warning list rather than in the state.", "`beyond the valve` where the duty is past what the trim can pass, and `not given` where the flow never arrived."]'::jsonb, 3, 'A blank in a results table reads as absence, and absence reads as nothing to do, which is why collapsing both into one empty result is such an expensive simplification.'),
  ('metering', 'intermediate', 'module', 'm06-travel-rangeability-and-the-verdict', 12, 'What coverage and what verdict come back on the case where the maximum flow is beyond the valve?', '["Two checks ran, so the coverage is 2 of 3, and the verdict is null with 1 warning raised.", "Every check ran, so the coverage is 3 of 3, and the verdict is null with no warning raised.", "Every check ran, so the coverage is 3 of 3, and the verdict is false with 1 warning raised.", "Two checks ran, so the coverage is 2 of 3, and the verdict is false with no warning raised."]'::jsonb, 2, 'That case is an answer. The check ran, it found that the duty asked of the valve is past what the trim can pass, and the action on it is to select a larger valve or a different trim.'),
  ('metering', 'intermediate', 'module', 'm06-travel-rangeability-and-the-verdict', 13, 'On how many of the travel cases did the engine withhold its pass verdict, and over what tree and rule?', '["4, counted over the 5 travel cases asked of the check, with a case counting when the engine returns a pass of false and at least one warning.", "2 cases. The tree is the 5 the check was run on and the rule admits a case whose pass comes back null.", "3, counted over the 5 travel cases asked of the check, with a case counting when fewer than 3 of the checks ran on it.", "1, counted over the 5 travel cases asked of the check, with a case counting when no flow at all was given for one of the three duties."]'::jsonb, 1, 'The engine returns a pass of null whenever a check could not run, which is what the rule is stated over.'),
  ('metering', 'intermediate', 'module', 'm06-travel-rangeability-and-the-verdict', 14, 'How does the engine''s message read where no minimum flow was given?', '["`no verdict: 2 of the 3 checks ran. Not run: the near-seat rangeability check: no minimum flow was given, so whether the valve can control at turndown is not known`", "`no verdict: 2 of the 3 checks ran. Not run: the maximum flow case: no maximum flow was given, so whether the valve can pass its design case is not known`", "`no verdict: 2 of the 3 checks ran. The near-seat rangeability check has been assumed to pass, because the two checks that ran were both clean`", "`no verdict: the near-seat rangeability check could not run, so the travel at the minimum duty has been taken as 0.000000 percent open instead`"]'::jsonb, 0, 'The message gives the coverage as a count of checks that ran, names the check that did not run, and says what is therefore unknown in terms of the engineering question.'),
  ('metering', 'intermediate', 'module', 'm06-travel-rangeability-and-the-verdict', 15, 'The two withheld cases both carry 0 warnings. Why does that matter?', '["A warning is suppressed while a verdict is withheld, so the count says nothing about whether the two checks that ran were clean.", "A warning is raised only on a failing verdict, so a withheld verdict can never carry one and the count is a formality.", "A warning is raised for each check that did not run, so a count of 0 says the checks all ran and the verdict is withheld for another reason.", "A warning is a finding and there is no finding on those cases, so what is carried in the verdict is an accounting statement about coverage."]'::jsonb, 3, 'A tool that reported a verdict over the checks it happened to run would have returned a pass on both, and a pass on a valve whose turndown behaviour has not been examined closes the item.'),
  ('metering', 'intermediate', 'final', null, 1, 'Which of the three pressure drop columns on the liquid march carries the same figure on every row?', '["The stated drop.", "The drop used.", "The allowable drop.", "None of them, since all three move as the outlet pressure is taken down."]'::jsonb, 2, 'The stated drop moves on every row and the drop used follows it until the service chokes, so the allowable drop is the one column reading 179.220032 psi from the first row to the last.'),
  ('metering', 'intermediate', 'final', null, 2, 'The liquid valve is asked for 171.300000 psia. What stated drop goes with that row, in psi?', '["75.600000", "106.900000", "46.900000", "136.900000"]'::jsonb, 0, 'The row at 140.000000 psia carries a stated drop of 106.900000 psi and the row at 200.000000 psia carries 46.900000 psi, both in psi.'),
  ('metering', 'intermediate', 'final', null, 3, 'At which outlet pressures does the engine report choked flow on the liquid march?', '["80.000000, 60.000000, 40.000000 and 28.740000 psia.", "60.000000, 40.000000, 28.740000 and 20.000000 psia.", "110.000000, 80.000000, 60.000000 and 40.000000 psia.", "40.000000, 28.740000 and 20.000000 psia."]'::jsonb, 1, 'Four of the nine rows carry the flag, and the crossing that decides which four sits at an outlet pressure of 67.679968 psia.'),
  ('metering', 'intermediate', 'final', null, 4, 'Which words open the choked flow message?', '["`choked flow: the stated pressure drop is beyond what the valve can use, so sizing on it would oversize the valve badly`", "`choked flow: the stated pressure drop is beyond what the valve can use, so the coefficient has been withheld for this row`", "`choked flow: the cavitation index sits below the last rung of the ladder, so the sizing basis moves to the allowable drop`", "`choked flow: the stated pressure drop is beyond what the valve can use, so sizing on it would undersize the valve badly`"]'::jsonb, 3, 'The message goes on to say that the allowable drop has been used instead and that this service wants a multistage or anti-cavitation trim.'),
  ('metering', 'intermediate', 'final', null, 5, 'What does the liquid critical pressure ratio factor read at the marched fluid''s own vapour and critical pressures?', '["0.892161", "0.960000", "0.680000", "0.900000"]'::jsonb, 0, 'That is the working value sitting inside the allowable drop that every choked row of the march is sized on.'),
  ('metering', 'intermediate', 'final', null, 6, 'What does the same factor read at the critical point?', '["0.892161", "0.680000", "0.960000", "0.666667"]'::jsonb, 1, 'It is the far end of the factor''s range, returned at the point where the vapour pressure and the critical pressure meet.'),
  ('metering', 'intermediate', 'final', null, 7, 'What is the crossing outlet pressure of 67.679968 psia useful for on a real project?', '["Telling a designer what inlet pressure the service was run at, since the stated drop is printed beside it.", "Telling a designer whether a proposed turndown case sits on the safe side of the valve''s own limit.", "Telling a designer which valve style the engine used, since the crossing is unique to one row of the style table.", "Telling a designer what the cavitation index will be at any outlet pressure above it, since the index is linear there."]'::jsonb, 1, 'The crossing belongs to the pressure recovery factor in force, so a valve supplied with a certified figure has its own crossing and a turndown study should be run against that.'),
  ('metering', 'intermediate', 'final', null, 8, 'The engine''s refusal spells out the arithmetic of the cavitation index. What sits on top of it?', '["The inlet pressure less the outlet pressure.", "The vapour pressure less the outlet pressure.", "The allowable drop less the stated drop.", "The inlet pressure less the vapour pressure."]'::jsonb, 3, 'The refusal says that with no vapour pressure the index is infinite and every service reads as stable, which is why the engine refuses rather than answering.'),
  ('metering', 'intermediate', 'final', null, 9, 'A liquid sizing arrives with the vapour pressure box empty. What does the repaired engine do?', '["It substitutes a default vapour pressure for the fluid family.", "It refuses the call by name and says why.", "It returns the index and marks the result provisional.", "It returns the index and omits the regime word."]'::jsonb, 1, 'The refusal names the quantity, gives the arithmetic that makes it necessary, and says where to find it, which is what makes it something a user can act on.'),
  ('metering', 'intermediate', 'final', null, 10, 'Two answers about damage come back on every liquid sizing row and they answer different questions. Which two?', '["The regime word and the choked flag.", "The regime word and the cavitation index.", "The choked flag and the flashing flag, which the march prints side by side.", "The cavitation index and the basis line beside it."]'::jsonb, 0, 'A row can carry a cavitation word with the flag still false, which means the valve is being damaged while the sizing equation is still working normally.'),
  ('metering', 'intermediate', 'final', null, 11, 'What pressures does the digest state for the flashing case?', '["An outlet pressure of 28.740000 psia against a vapour pressure of 26.740000 psia.", "An outlet pressure of 20.000000 psia against a vapour pressure of 28.740000 psia.", "An outlet pressure of 26.740000 psia against a vapour pressure of 28.740000 psia.", "An outlet pressure of 26.740000 psia against a vapour pressure of 20.000000 psia."]'::jsonb, 2, 'The engine returns flashing true and the regime word flashing on that case, and it turns the flag on at exactly the stated vapour pressure.'),
  ('metering', 'intermediate', 'final', null, 12, 'What is leaving the valve on a flashing service?', '["A liquid carrying dispersed bubbles that collapse a few diameters downstream.", "A vapour stream, since the whole of the liquid flashes across the restriction.", "A liquid at its bubble point, which the expanded outlet then returns to a single phase.", "A two-phase mixture, which stays that way rather than condensing back."]'::jsonb, 3, 'The vapour occupies a great deal more volume than the liquid it came from, which is why the message calls for an expanded outlet.'),
  ('metering', 'intermediate', 'final', null, 13, 'Where does the damage happen on a flashing service?', '["At the plug and the seat, where the implosions are concentrated.", "In the valve outlet and the downstream pipe.", "In the body cavity, where the two phases separate out again.", "At the inlet, where the fluid first meets the restriction."]'::jsonb, 1, 'A high velocity mixture of liquid droplets and vapour scours whatever it meets, which is an erosion problem rather than an implosion problem.'),
  ('metering', 'intermediate', 'final', null, 14, 'Why does this course grade no regime word?', '["The regime word is derived from the choked flag, so grading it would grade the flag twice.", "The regime word changes between the stated drop basis and the allowable drop basis.", "Neither of the two ladder thresholds is read from a standard. Both are this engine''s stated screen, which it exports so a reader can see them.", "The regime word is not exported by the module, so a learner cannot check it against anything."]'::jsonb, 2, 'Acceptability on a cavitating service depends on the trim, the materials, the duty cycle and how much of the year the valve spends there, none of which the index knows.'),
  ('metering', 'intermediate', 'final', null, 15, 'The gas valve is asked for an outlet of 230.000000 psia. What is x there?', '["0.189955", "0.068449", "0.306197", "0.432969"]'::jsonb, 1, 'The ratio at an outlet pressure of 200.000000 psia is 0.189955 and at 171.300000 psia it is 0.306197.'),
  ('metering', 'intermediate', 'final', null, 16, 'And at an outlet pressure of 30.000000 psia?', '["0.797489", "0.716484", "0.680357", "0.878493"]'::jsonb, 3, 'The engine''s message on that row quotes the ratio as x of 0.878 against the terminal 0.680.'),
  ('metering', 'intermediate', 'final', null, 17, 'Which three rows of the gas march come back with the choked flag true?', '["The rows at outlet pressures of 90.000000, 70.000000 and 50.000000 psia.", "The rows at outlet pressures of 70.000000, 50.000000 and 30.000000 psia.", "The rows at outlet pressures of 110.000000, 90.000000, 70.000000 and 50.000000 psia.", "The rows at outlet pressures of 50.000000 and 30.000000 psia."]'::jsonb, 1, 'The gas valve begins to choke at an outlet of 78.919821 psia, and the terminal ratio is what the sizing is done on below that.'),
  ('metering', 'intermediate', 'final', null, 18, 'Helium and argon service sits at a specific heat ratio of 1.660000. What factor comes back there?', '["0.928571", "1.000000", "1.185714", "0.857143"]'::jsonb, 2, 'A specific heat ratio of 1.660000 covers the monatomic gases, which in a plant means helium and argon service.'),
  ('metering', 'intermediate', 'final', null, 19, 'The same factor is asked for a ratio of 1.300000. What comes back?', '["0.857143", "0.928571", "0.785714", "1.185714"]'::jsonb, 1, 'The factor at 1.200000 is 0.857143 and at 1.100000 it is 0.785714.'),
  ('metering', 'intermediate', 'final', null, 20, 'What does the engine say about whether its pressure recovery factors are cited?', '["They are cited to the sizing standard the coefficients are defined in.", "They are cited to the vendor catalogues the styles were averaged from.", "They are cited in the module''s own source comments, which the digest quotes.", "They are not cited to a document in this repository."]'::jsonb, 3, 'Following them back to a published source from here is not possible, which is what a reader has to know before quoting one in a calculation.'),
  ('metering', 'intermediate', 'final', null, 21, 'A certified recovery factor is genuinely unavailable on a project. What does the course say to do?', '["Use the style average silently, since it is the best figure available and a note about it invites a question nobody can answer.", "Say so explicitly in the calculation, quote the table value as the engine''s own, and treat the boundary position as provisional until the vendor confirms it.", "Use the largest figure the table carries, since the engine treats it as the default wherever nothing has been stated.", "Refuse to size the valve at all, since the boundary cannot be established and the coefficient past it cannot be defended."]'::jsonb, 1, 'The failure to avoid is the silent one, where a style average gets copied into a document that later reads as though it had been confirmed.'),
  ('metering', 'intermediate', 'final', null, 22, 'A valve drop of 10.000000 psi sits in a circuit that takes 120.000000 psi in all. What comes back?', '["0.208333", "0.333333", "0.083333", "0.458333"]'::jsonb, 2, 'The engine takes the valve drop over the total and returns the fraction, with no reference to the flow, the fluid or the trim.'),
  ('metering', 'intermediate', 'final', null, 23, 'What authority does a 55.000000 psi share of a 120.000000 psi circuit give?', '["0.458333", "0.583333", "0.333333", "0.708333"]'::jsonb, 0, 'That figure sits between the two rungs the engine states for itself, which is the interesting place for a design to land.'),
  ('metering', 'intermediate', 'final', null, 24, 'The hydraulic figure for a circuit''s total drop turns out to be a guess. What does that do to the word printed beside the authority?', '["It is withheld, because the engine refuses a verdict over an input it cannot check.", "It is unaffected, because the word is read off the valve drop rather than off the total.", "It is marked provisional, because the engine carries the provenance of every input into its result.", "It inherits the guess without showing it."]'::jsonb, 3, 'A fraction is only as good as the arithmetic behind its denominator, and a word carries none of that provenance with it.'),
  ('metering', 'intermediate', 'final', null, 25, 'What happens to the drop available to the valve as the flow rises?', '["It rises, because the valve is opening and its own resistance is falling away.", "It falls, because friction losses in the rest of the circuit rise with flow and the total is fixed.", "It holds still, because the total drop and the circuit resistance both rise together.", "It falls, because the pump is being throttled back to hold the set point."]'::jsonb, 1, 'If the valve was taking a small fraction to begin with, opening it hands most of the newly released pressure straight to the pipework.'),
  ('metering', 'intermediate', 'final', null, 26, 'Why is the characteristic recommendation read off the authority rather than off the service?', '["The distortion the trim is chosen to cancel is produced by the circuit around the valve, so the fraction of the drop the circuit takes is the variable that says how much cancelling is needed.", "The service is not an argument of the recommendation, which takes the characteristic already fitted and checks it.", "The authority is the only figure in the module that a vendor certifies, so it is the only defensible basis for a recommendation.", "The service decides the coefficient and the coefficient decides the travel, so reading the characteristic off the service would be circular."]'::jsonb, 0, 'The trim is chosen to cancel a known distortion, and choosing it for a circuit that does not apply that distortion produces a loop that is bent the other way instead.'),
  ('metering', 'intermediate', 'final', null, 27, 'Where does the refusal on an unrecognised inherent characteristic fire?', '["At the recommendation, which is the function that produces characteristic words.", "At the authority calculation, which is the first function in the chain.", "At the travel check, which is the function that was handed the unknown word.", "At whichever function is called first, since both carry the same guard."]'::jsonb, 2, 'The recommendation never produces a word outside the pair, so the guard belongs where an outside word can actually arrive.'),
  ('metering', 'intermediate', 'final', null, 28, 'Three things have to be true wherever two functions exchange a word rather than a number. What are they?', '["The two sets are identical, anything outside them is mapped to the nearest member, and the mapping is reported in the result.", "The set one produces sits inside the set the other accepts, anything outside it is refused by name, and the refusal says which words are known.", "The set one produces sits inside the set the other accepts, anything outside it is passed through untouched, and the caller checks it.", "The two sets are versioned together, anything outside them raises a warning, and the warning names the version the word came from."]'::jsonb, 1, 'A silent default produces an answer of the right type and the wrong value, and nothing downstream can tell that it happened.'),
  ('metering', 'intermediate', 'final', null, 29, 'A one scfh bleed is put through the screen. What power in kW does it carry?', '["0.00133650 kW", "2312.85 kW", "34486.0 kW", "1000.000000 kW"]'::jsonb, 0, 'Its message quotes that power as 0.00134 kW when it explains why the band was held down.'),
  ('metering', 'intermediate', 'final', null, 30, 'What stream power does the moderate station flow carry?', '["1000 kW", "0.00133650 kW", "2312.85 kW", "12.000000 kW"]'::jsonb, 2, 'That probe sits at a pressure ratio of 6.000000, with a ratio band of high and a band of high.'),
  ('metering', 'intermediate', 'final', null, 31, 'A transmission volume is throttled and the screen is run. Which figure is its power in kW?', '["1 kW", "34486.0 kW", "0.00133650 kW", "1.898734 kW"]'::jsonb, 1, 'The engine''s message on that probe says the power is above 1000 kW, which is not a quiet valve at any pressure ratio.'),
  ('metering', 'intermediate', 'final', null, 32, 'The engine''s note says what to use the band for. What is it?', '["To answer the question at concept stage.", "To set an acoustic lagging thickness.", "To close an item on the noise register.", "To know whether to ask the question."]'::jsonb, 3, 'The rest of the note names the method and the geometry a real prediction needs, which is what the band cannot supply.'),
  ('metering', 'intermediate', 'final', null, 33, 'Which of the three probes did the engine leave where the pressure ratio had put it?', '["The one scfh bleed at a pressure ratio near twelve.", "The hundred million scfh at a pressure ratio near two.", "The moderate station flow at a pressure ratio near six.", "None of them, since the stream power moved all three."]'::jsonb, 2, 'Its ratio band and its final band both read high, so nothing was moved on it and the digest prints no reason to look further.'),
  ('metering', 'intermediate', 'final', null, 34, 'Whose are the two sets of thresholds the screen reads against?', '["Both sets are this engine''s stated screen.", "Both sets are read from the method the note names.", "The ratio set is the engine''s own and the power set is published.", "The power set is the engine''s own and the ratio set is published."]'::jsonb, 0, 'They are exported so that they can be read and, if an organisation prefers its own, replaced.'),
  ('metering', 'intermediate', 'final', null, 35, 'A valve is flagged by the screen. What goes into the design document?', '["That the valve is expected to exceed the site noise limit at the stated distance.", "That the screening indication flagged it and that the proper calculation is outstanding.", "That the valve has been sized for a low noise trim and the item can be closed.", "That the band was returned by a method the engine names, with the band word beside it."]'::jsonb, 1, 'The practical rule is to act on the band and quote the method, so that a later reader cannot mistake a screening output for a prediction.'),
  ('metering', 'intermediate', 'final', null, 36, 'A rangeability of 50 and an equal percentage curve. What normal duty travel does the check report?', '["37.222222", "47.956430", "83.997848", "74.737770"]'::jsonb, 3, 'That figure is uninterpretable without its characteristic and its rangeability, and both are properties a vendor states for the specific trim.'),
  ('metering', 'intermediate', 'final', null, 37, 'How far open is the valve at its maximum duty on the clean case, in percent?', '["83.997848", "74.737770", "47.956430", "0.000000"]'::jsonb, 0, 'Nothing was refused and nothing was withheld on that case, so the figure is one the engine is prepared to stand behind.'),
  ('metering', 'intermediate', 'final', null, 38, 'How many of its checks does the engine run when no maximum flow is given?', '["3 of the 3.", "1 of the 3.", "2 of the 3.", "None of them, since a missing flow stops the check running at all."]'::jsonb, 2, 'The verdict is withheld on that case and the warning count is 0, because a warning is a finding and there is no finding.'),
  ('metering', 'intermediate', 'final', null, 39, 'What does the engine say is not known where no maximum flow was given?', '["Whether the valve can control at turndown.", "Whether the valve can pass its design case.", "Whether the valve is beyond its rangeability.", "Whether the minimum flow lands hard against the seat."]'::jsonb, 1, 'Where no minimum flow is given it is the near-seat rangeability check that did not run, and what is then not known is whether the valve can control at turndown.'),
  ('metering', 'intermediate', 'final', null, 40, 'Rangeability is a property the vendor states. What span does it name?', '["The span between the maximum and the minimum flow the check was given.", "The ratio of the travel at the maximum duty to the travel at the minimum duty.", "The fraction of the full stroke over which the inherent characteristic holds its shape.", "The span between the largest and the smallest coefficient the trim can meter with."]'::jsonb, 3, 'It is a property the vendor states for the specific trim, and one assumed rather than confirmed moves every travel figure the check produces.'),
  ('metering', 'intermediate', 'final', null, 41, 'Three things must never be rendered as the same empty cell. What are they?', '["A number, a refusal and an absence.", "A number, a warning and a refusal.", "A refusal, a warning and an absence.", "A number, an absence and a rounding to zero."]'::jsonb, 0, 'A result has to carry its own coverage, and a table that renders all three as an empty cell has destroyed the distinction before any reader gets to it.'),
  ('metering', 'intermediate', 'final', null, 42, 'Why would a pass reported over the checks that happened to run be the more dangerous answer?', '["It reopens the item, so the review spends its time on a case the engine has already cleared.", "It contradicts the warning list, so a reader has to decide which of the two returns to believe.", "It closes the item, so nobody looks again at a valve whose turndown behaviour is still unknown.", "It reports a verdict the engine cannot reproduce, so the result fails to repeat on a second run."]'::jsonb, 2, 'An answer refused by name leaves a reader with something to do. One quietly produced from incomplete work leaves them with nothing to do and no reason to look again.');
